import math

def normal_cdf(x):
    return 0.5*math.erfc(-x/math.sqrt(2.0))

def european_pair(spot,strike,rate,years,vol):
    # No dividends,European exercise,continuous annual rate and annualized vol.
    for value,low,high in ((spot,1.0,10000.0),(strike,1.0,10000.0),(rate,-0.2,0.5),(years,0.0,10.0),(vol,0.0,2.0)):
        if type(value) is not float or not math.isfinite(value) or not low<=value<=high:
            raise ValueError("invalid bounded pricing input")
    if years==0.0:return max(spot-strike,0.0),max(strike-spot,0.0)
    discounted_strike=strike*math.exp(-rate*years)
    if vol==0.0:return max(spot-discounted_strike,0.0),max(discounted_strike-spot,0.0)
    if years<1e-6 or vol<1e-6:
        raise ValueError("positive time/vol below teaching numerical domain")
    width=vol*math.sqrt(years)
    d1=(math.log(spot/strike)+(rate+0.5*vol*vol)*years)/width
    d2=d1-width
    if max(abs(d1),abs(d2))>8.0:
        raise ValueError("normal tail outside teaching numerical domain")
    # Compute the out-of-money side directly,then parity for the other side.
    if spot<=discounted_strike:
        call=spot*normal_cdf(d1)-discounted_strike*normal_cdf(d2)
        put=call+discounted_strike-spot
    else:
        put=discounted_strike*normal_cdf(-d2)-spot*normal_cdf(-d1)
        call=put+spot-discounted_strike
    return call,put

def fixed_call_iv(target,maxiter=80):
    # Inverse only for S=K100,r.05,T1,no dividends,European call.
    if type(target) is not float or not math.isfinite(target) or not 0.0<=target<=100.0:
        raise ValueError("invalid target price")
    if type(maxiter) is not int or not 1<=maxiter<=100:
        raise ValueError("invalid iteration budget")
    def price(vol):return european_pair(100.0,100.0,0.05,1.0,vol)[0]
    lo,hi=0.05,1.5
    plo,phi=price(lo),price(hi)
    if not plo<=target<=phi:raise ValueError("target outside supported volatility bracket")
    if target==plo:return lo,0.0,(lo,lo),0
    if target==phi:return hi,0.0,(hi,hi),0
    for iteration in range(1,maxiter+1):
        mid=(lo+hi)/2.0
        residual=price(mid)-target
        if residual==0.0:lo=hi=mid
        elif residual<0.0:lo=mid
        else:hi=mid
        if abs(residual)<=1e-8 and hi-lo<=1e-8:
            return mid,residual,(lo,hi),iteration
    raise RuntimeError("volatility solve did not converge")

synthetic=european_pair(100.0,100.0,0.05,1.0,0.2)[0]
vol,residual,bracket,iterations=fixed_call_iv(synthetic)
print(f"vol={vol:.8f}")
print(abs(residual)<=1e-8,bracket[1]-bracket[0]<=1e-8)
try:fixed_call_iv(0.0)
except ValueError as error:print(error)
try:fixed_call_iv(synthetic,1)
except RuntimeError as error:print(error)
